def march(k,n):
    h=4/n;e=b=r=80.;rows=[[0.,80.,80.,80.,80.]]
    f=lambda y:-k*(y-20)
    for j in range(n):
        e=e+h*f(e);b=20+(b-20)/(1+k*h)
        s1=f(r);s2=f(r+h*s1/2);s3=f(r+h*s2/2);s4=f(r+h*s3)
        r=r+h*(s1+2*s2+2*s3+s4)/6
        t=(j+1)*h;rows.append([t,20+60*np.exp(-k*t),e,b,r])
    return np.array(rows)
for k in [0.,1.,2.]:
    for n in [4,8,16,32,64]:
        rows=march(k,n);last=rows[-1]
        print('k/N/h/终点解析-E-BE-RK/三误差/预算E-闭式BE-RK:',k,n,4/n,last[1:],abs(last[2:]-last[1]),[n,n,4*n])
print('默认全网格:',march(1,8))
print('Euler振荡边界:',march(2,4)[:,[0,2]])
